using BuildingFlow.Domain;
using Xunit;
namespace BuildingFlow.UnitTests;

public sealed class DomainTests
{
    [Fact] public void EmptyPropertyTypeCanChangeWithItsMetadata() {var property=Create();property.UpdateDetails(" Apartment ","City","District","Address",true,8,PropertyType.APARTMENT);Assert.Equal(PropertyType.APARTMENT,property.Type);Assert.Equal(8,property.FloorCount);Assert.Equal("Apartment",property.Name);property.UpdateDetails("Site","City","District","Address",true,null,PropertyType.SITE);Assert.Null(property.FloorCount);Assert.Equal(PropertyType.SITE,property.Type);}
    [Theory][InlineData(true)][InlineData(false)] public void PopulatedPropertyTypeCannotChange(bool apartment) {var property=new Property("Original","City","District","Address",apartment?PropertyType.APARTMENT:PropertyType.SITE);if(apartment)property.AddUnit("1",0,100).SetEnabled(false);else property.AddBuilding("A").SetEnabled(false);Assert.Throws<InvalidOperationException>(()=>property.UpdateDetails("Changed","City","District","Address",false,null,PropertyType.MIXED));Assert.Equal("Original",property.Name);Assert.True(property.IsEnabled);}
    [Fact] public void InvalidTypeOrMetadataLeavesPropertyUnchanged() {var property=Create();Assert.Throws<ArgumentException>(()=>property.UpdateDetails("Changed","City","District","Address",false,null,(PropertyType)99));Assert.Throws<ArgumentException>(()=>property.UpdateDetails("Changed","City","District","Address",false,8,PropertyType.MIXED));Assert.Equal(PropertyType.SITE,property.Type);Assert.Equal("BuildingFlow",property.Name);Assert.True(property.IsEnabled);Assert.Null(property.FloorCount);}
    [Fact] public void StandaloneApartmentUnitsHaveNoArtificialBuilding() {var property=new Property("ABC","City","District","Address",PropertyType.APARTMENT,8);var unit=property.AddUnit("1",-1,120);Assert.Null(unit.BuildingId);Assert.Equal(property.Id,unit.PropertyId);Assert.Empty(property.Buildings);Assert.Throws<InvalidOperationException>(()=>property.AddBuilding("Artificial"));Assert.Throws<InvalidOperationException>(()=>property.AddUnit("2",1,100,UnitType.OFFICE));}
    [Fact] public void SiteUnitsRequireBuildingAndCarryBothParentIds() {var property=Create();Assert.Throws<InvalidOperationException>(()=>property.AddUnit("1",1,100));var building=property.AddBuilding("Tower",8);var unit=building.AddUnit("1",1,100,UnitType.OFFICE);Assert.Equal(property.Id,unit.PropertyId);Assert.Equal(building.Id,unit.BuildingId);Assert.Equal(8,building.FloorCount);}
    private static Property Create() => new("BuildingFlow", "İstanbul", "Kadıköy", "Test address");
    [Fact] public void SiteCreatesWithIdentityAndTrimmedName() { var site = new Property(" Property ", "City", "District", "Address"); Assert.NotEqual(Guid.Empty, site.Id); Assert.Equal("Property", site.Name); Assert.True(site.IsEnabled); }
    [Theory][InlineData("")][InlineData(" ")] public void RejectsEmptySiteName(string name) => Assert.Throws<ArgumentException>(() => new Property(name, "City", "District", "Address"));
    [Fact] public void BlockHasSiteIdentity() { var site = Create(); Assert.Equal(site.Id, site.AddBuilding("A").PropertyId); }
    [Fact] public void RejectsEmptyBlockName() => Assert.Throws<ArgumentException>(() => Create().AddBuilding(" "));
    [Fact] public void RejectsDuplicateBlockIgnoringCase() { var site = Create(); site.AddBuilding("A"); Assert.Throws<ArgumentException>(() => site.AddBuilding(" a ")); }
    [Theory][InlineData(0)][InlineData(-1)] public void RejectsNonPositiveArea(int area) => Assert.Throws<ArgumentOutOfRangeException>(() => Create().AddBuilding("A").AddUnit("1", 0, area));
    [Fact] public void ApartmentPreservesRelationshipAndBasementFloor() { var block = Create().AddBuilding("A"); var apartment = block.AddUnit("1", -1, 120); Assert.Equal(block.Id, apartment.BuildingId); Assert.Equal(-1, apartment.Floor); }
    [Fact] public void RejectsEmptyApartmentNumber() => Assert.Throws<ArgumentException>(() => Create().AddBuilding("A").AddUnit(" ", 1, 120));
    [Fact] public void RejectsDuplicateApartment() { var block = Create().AddBuilding("A"); block.AddUnit("A1", 0, 100); Assert.Throws<ArgumentException>(() => block.AddUnit(" a1 ", 0, 100)); }
    [Fact] public void SiteEditIsAtomic() { var site=Create(); Assert.Throws<ArgumentException>(()=>site.UpdateDetails("New","City","District"," ",false)); Assert.Equal("BuildingFlow",site.Name);Assert.True(site.IsEnabled); }
    [Fact] public void BlockRenameCannotDuplicateSibling() { var site=Create();site.AddBuilding("A");var block=site.AddBuilding("B");Assert.Throws<ArgumentException>(()=>site.UpdateBuilding(block.Id," a ",false));Assert.Equal("B",block.Name);Assert.True(block.IsEnabled);site.UpdateBuilding(block.Id," C ",false);Assert.Equal("C",block.Name);Assert.False(block.IsEnabled); }
    [Fact] public void ApartmentEditValidatesBeforeMutating() { var block=Create().AddBuilding("A");var apartment=block.AddUnit("1",-1,100);Assert.Throws<ArgumentOutOfRangeException>(()=>block.UpdateUnit(apartment.Id,"New",3,1.001m,false));Assert.Equal("1",apartment.Number);Assert.Equal(-1,apartment.Floor);Assert.True(apartment.IsEnabled); }
    [Fact] public void ApartmentRenameCannotDuplicateSibling() { var block=Create().AddBuilding("A");block.AddUnit("A1",0,100);var apartment=block.AddUnit("B1",1,110);Assert.Throws<ArgumentException>(()=>block.UpdateUnit(apartment.Id," a1 ",2,120,false));Assert.Equal("B1",apartment.Number);block.UpdateUnit(apartment.Id," C1 ",-2,120.25m,false);Assert.Equal("C1",apartment.Number);Assert.False(apartment.IsEnabled); }
}
